INSERT INTO `posts` VALUES (6,2,'test-aaaa','test aaaa','',3,'/assets/uploads/post_cover_1767781366_f16e8a45.png','<h1 align=\"center\" style=\"margin:0in;margin-bottom:.0001pt;text-align:center\"><a name=\"_Toc192576138\"><span style=\"font-size:15.0pt;line-height:150%\">CHƯƠNG 1:\r\nTỔNG QUAN VỀ CƠ SỞ THỰC TẬP</span></a><span style=\"font-size:15.0pt;line-height:\r\n150%\"><o:p></o:p></span></h1><h2 style=\"margin:0in\"><a name=\"_Toc192576139\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">1.1. Giới thiệu chung</span></a><span style=\"font-size:14.0pt;\r\nline-height:150%\"><o:p></o:p></span></h2><h3 style=\"margin:0in\"><a name=\"_Toc192576140\">1.1.1. Quá trình hình thành và\r\nphát triển</a></h3><h3 style=\"margin:0in\"><img src=\"data:image/png;base64,\" alt=\"\"><o:p></o:p></h3><h4 style=\"margin:0in\">\r\n\r\n\r\n\r\n\r\n\r\n<p class=\"MsoNormal\" align=\"center\" style=\"text-align:center;page-break-after:avoid\"><v:shapetype id=\"_x0000_t75\" coordsize=\"21600,21600\" o:spt=\"75\" o:preferrelative=\"t\" path=\"m@4@5l@4@11@9@11@9@5xe\" filled=\"f\" stroked=\"f\">\r\n <v:stroke joinstyle=\"miter\">\r\n <v:formulas>\r\n  <v:f eqn=\"if lineDrawn pixelLineWidth 0\">\r\n  <v:f eqn=\"sum @0 1 0\">\r\n  <v:f eqn=\"sum 0 0 @1\">\r\n  <v:f eqn=\"prod @2 1 2\">\r\n  <v:f eqn=\"prod @3 21600 pixelWidth\">\r\n  <v:f eqn=\"prod @3 21600 pixelHeight\">\r\n  <v:f eqn=\"sum @0 0 1\">\r\n  <v:f eqn=\"prod @6 1 2\">\r\n  <v:f eqn=\"prod @7 21600 pixelWidth\">\r\n  <v:f eqn=\"sum @8 21600 0\">\r\n  <v:f eqn=\"prod @7 21600 pixelHeight\">\r\n  <v:f eqn=\"sum @10 21600 0\">\r\n </v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:formulas>\r\n <v:path o:extrusionok=\"f\" gradientshapeok=\"t\" o:connecttype=\"rect\">\r\n <o:lock v:ext=\"edit\" aspectratio=\"t\">\r\n</o:lock></v:path></v:stroke></v:shapetype><v:shape id=\"Picture_x0020_1\" o:spid=\"_x0000_i1025\" type=\"#_x0000_t75\" alt=\"Logo\" style=\"width:170.25pt;height:87.75pt;visibility:visible;\r\n mso-wrap-style:square\">\r\n <v:imagedata src=\"file:///C:/Users/MANH/AppData/Local/Temp/msohtmlclip1/01/clip_image001.png\" o:title=\"Logo\">\r\n</v:imagedata></v:shape><o:p></o:p></p>\r\n\r\n<p class=\"MsoCaption\" align=\"center\" style=\"text-align:center\"><a name=\"_Toc192535490\"><b><span style=\"font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\">Hình 1.</span></b></a><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535490\'></span><span style=\'mso-element:field-begin\'></span><span\r\nstyle=\'mso-bookmark:_Toc192535490\'><b style=\'mso-bidi-font-weight:normal\'><span\r\nstyle=\'font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\'> SEQ\r\nHình_1. \\* ARABIC <span style=\'mso-element:field-separator\'></span></span></b></span><![endif]--><b><span style=\"font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\">1</span></b><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535490\'></span><span style=\'mso-element:field-end\'></span><![endif]--><b><span style=\"font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\">: Logo Công\r\nty</span></b><b><span style=\"font-size: 14pt; color: windowtext; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-indent:.5in\"><a name=\"_heading=h.w16bjt4h5x9h\"></a>Công\r\nty cổ phần giải pháp phần mềm tài chính (FSS) được thành lập ngày 18/03/2008\r\nbởi các chuyên gia đã có nhiều năm kinh nghiệm trong việc phát triển và triển\r\nkhai giải pháp công nghệ thông tin cho các đơn vị hoạt động trong lĩnh vực tài\r\nchính, ngân hàng, chứng khoán tại Việt Nam và khu vực.<o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-indent:.5in\">Sau 16 năm hoạt động, với một đội\r\nngũ hơn 400 chuyên gia làm việc trong lĩnh vực phần mềm, FSS đã trở thành một\r\ntrong những công ty phần mềm tài chính – ngân hàng hàng đầu tại Việt Nam và\r\nđược nhiều khách hàng tin tưởng, lựa chọn. Khách hàng của FSS bao gồm các ngân\r\nhàng và các công ty chứng khoán lớn như BIDV, TechcomBank, VPBank, MBBank,\r\nVNDirect, VCBS, BSC, BVSC,…<o:p></o:p></p></h4>',1,0,'2026-01-07 10:22:46','2026-01-08 11:09:27',1);
